<?php
namespace AppBancos\Application;
use AppBancos\Repository\ReglaAsignacionRepository;use InvalidArgumentException;
final class GuardarReglaAsignacion{private$r;private$e;public function __construct(ReglaAsignacionRepository$r,EjecutorComandoIdempotente$e){$this->r=$r;$this->e=$e;}public function ejecutar(array$i,$op,$clave){$c=$this->id($i['configuracion_id']??null,'configuracion_id');$rid=($i['regla_asignacion_id']??null)===null||trim((string)$i['regla_asignacion_id'])===''?null:$this->id($i['regla_asignacion_id'],'regla_asignacion_id');$s=filter_var($i['subtipo_valor_zetti_id']??null,FILTER_VALIDATE_INT);if($s===false||$s<1||$s>32767){throw new InvalidArgumentException('subtipo_valor_zetti_id esta fuera de rango.');}$u=$this->id($i['usuario_id']??null,'usuario_id');$m=$this->motivo($i['motivo']??null);$x=['configuracion_id'=>$c,'regla_asignacion_id'=>$rid,'subtipo_valor_zetti_id'=>(int)$s,'usuario_id'=>$u,'motivo'=>$m];return$this->e->ejecutar($rid===null?'configuracion.crear-asignacion':'configuracion.versionar-asignacion',$clave,$op,$x,['accion'=>$rid===null?'CONFIGURACION_CREAR_ASIGNACION':'CONFIGURACION_VERSIONAR_ASIGNACION','recurso_tipo'=>'REGLA_ASIGNACION','recurso_id'=>$rid,'resultado'=>'EXITOSA','detalles'=>['motivo'=>$m]],function()use($x,$op){$r=$this->r->guardar($x['configuracion_id'],$x['regla_asignacion_id'],$x['subtipo_valor_zetti_id'],$x['usuario_id'],$op,$x['motivo']);return['codigo_http'=>$x['regla_asignacion_id']===null?201:200,'respuesta'=>$r];});}private function id($v,$c){$v=trim((string)$v);if(!preg_match('/^[0-9]{1,20}$/',$v)||($v=ltrim($v,'0'))===''){throw new InvalidArgumentException($c.' es invalido.');}return$v;}private function motivo($v){$v=trim((string)$v);if(mb_strlen($v,'UTF-8')<3||mb_strlen($v,'UTF-8')>200){throw new InvalidArgumentException('motivo debe contener entre 3 y 200 caracteres.');}return$v;}}
